from __future__ import annotations

import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO_ROOT))

from engine.arbitration import event_static_keys  # noqa: E402
from engine.config_loader import Config, load_config  # noqa: E402
from tools.codegen_c_table import c_ident  # noqa: E402

SRC_DIR = REPO_ROOT / "mcu" / "firmware" / "app" / "src"

def render_arbitration_source(cfg: Config) -> str:
    keys = event_static_keys(cfg)
    lines = [
        "/* AUTO-GENERATED FILE -- DO NOT HAND-EDIT.",
        f" * Generated by mcu/host_bridge/codegen_arbitration_table.py from {cfg.config_id}'s",
        " * conflict_resolution table via engine.arbitration.event_static_keys().",
        " * Fields: rank, class_key, reset_key (see engine_arbitration.h). */",
        '#include "engine_arbitration.h"',
        "",
        "const engine_arbitration_key_t g_event_arbitration[EVENT_COUNT] = {",
    ]
    for eid in cfg.events:
        rank, class_key, reset_key = keys[eid]
        lines.append(
            f"    [EVENT_{c_ident(eid)}] = {{ .rank = {rank}u, .class_key = {class_key}u, "
            f".reset_key = {reset_key}u }},"
        )
    lines += ["};", ""]
    return "\n".join(lines)

def write_arbitration_table(config_id: str, out_dir: Path = SRC_DIR) -> Path:
    cfg = load_config(REPO_ROOT / "config" / f"{config_id}.yaml")
    path = out_dir / "engine_arbitration_table.c"
    path.write_text(render_arbitration_source(cfg))
    return path

if __name__ == "__main__":
    print(write_arbitration_table(sys.argv[1] if len(sys.argv) > 1 else "config-a"))
